import React from 'react';
import { Button, LinListToolbar } from '@linm-soft-org/linm-web-common-components';
import styles from './CatalogFormToolbar.module.css';

export type CatalogFormMode = 'create' | 'edit' | 'view' | 'copy';

export type CatalogFormToolbarProps = {
  testIdPrefix: string;
  title: string;
  mode: CatalogFormMode;
  saving?: boolean;
  canSave?: boolean;
  canEdit?: boolean;
  canCopy?: boolean;
  canDelete?: boolean;
  copySourceCode?: string;
  extraActions?: React.ReactNode;
  onBack: () => void;
  onCancel: () => void;
  onSave: () => void;
  onEdit?: () => void;
  onCopy?: () => void;
  onDelete?: () => void;
};

function tid(prefix: string, name: string) {
  return `${prefix}-${name}`;
}

export const CatalogFormToolbar: React.FC<CatalogFormToolbarProps> = ({
  testIdPrefix,
  title,
  mode,
  saving = false,
  canSave = true,
  canEdit = false,
  canCopy = false,
  canDelete = false,
  copySourceCode,
  extraActions,
  onBack,
  onCancel,
  onSave,
  onEdit,
  onCopy,
  onDelete,
}) => {
  const isView = mode === 'view';
  const isCreate = mode === 'create' || mode === 'copy';
  const saveLabel = isCreate ? 'Tạo mới' : 'Lưu thay đổi';

  const right = (
    <div className={styles.toolbarRight}>
      {extraActions}
      {isView ? (
        <>
          {canEdit && onEdit ? (
            <Button
              variant="primary"
              size="sm"
              data-testid={tid(testIdPrefix, 'btn-to-edit')}
              onClick={onEdit}
            >
              <i className="fas fa-pen" aria-hidden /> Sửa
            </Button>
          ) : null}
          {canCopy && onCopy ? (
            <Button
              variant="secondary"
              size="sm"
              data-testid={tid(testIdPrefix, 'btn-to-copy')}
              onClick={onCopy}
            >
              <i className="fas fa-copy" aria-hidden /> Sao chép
            </Button>
          ) : null}
          {canDelete && onDelete ? (
            <Button
              variant="secondary"
              size="sm"
              data-testid={tid(testIdPrefix, 'btn-delete')}
              onClick={onDelete}
            >
              <i className="fas fa-trash" aria-hidden /> Xóa
            </Button>
          ) : null}
        </>
      ) : (
        <>
          <Button
            variant="secondary"
            size="sm"
            data-testid={tid(testIdPrefix, 'btn-cancel')}
            onClick={onCancel}
            disabled={saving}
            title="Hủy thay đổi"
          >
            <i className="fas fa-times" aria-hidden /> Hủy
          </Button>
          <Button
            variant="primary"
            size="sm"
            data-testid={tid(testIdPrefix, 'btn-save')}
            onClick={onSave}
            disabled={saving || !canSave}
          >
            <i className={`fas ${saving ? 'fa-spinner fa-spin' : 'fa-save'}`} aria-hidden />{' '}
            {saveLabel}
          </Button>
        </>
      )}
    </div>
  );

  return (
    <div className={styles.stickyTop} data-testid={tid(testIdPrefix, 'z1')}>
      <LinListToolbar
        testIdPrefix={testIdPrefix}
        profile="generic"
        actions={[
          {
            id: 'back',
            placement: 'left',
            testId: tid(testIdPrefix, 'back-btn'),
            render: () => (
              <Button
                variant="secondary"
                size="sm"
                data-testid={tid(testIdPrefix, 'btn-back')}
                onClick={onBack}
              >
                <i className="fas fa-arrow-left" aria-hidden /> Quay lại
              </Button>
            ),
          },
          {
            id: 'right',
            placement: 'right',
            render: () => right,
          },
        ]}
      />
      <div className={styles.titleBlock}>
        <h1 className={styles.title} data-testid={tid(testIdPrefix, 'title')}>
          {title}
        </h1>
        {isView ? (
          <div className={styles.viewHint} data-testid={tid(testIdPrefix, 'view-hint')}>
            <i className="fas fa-eye" aria-hidden /> Chế độ xem — nhấn <strong>Sửa</strong> để
            chỉnh sửa
          </div>
        ) : copySourceCode?.trim() && mode === 'copy' ? (
          <div className={styles.editHint} data-testid={tid(testIdPrefix, 'copy-hint')}>
            <i className="fas fa-copy" aria-hidden /> Bạn đang thực hiện copy từ{' '}
            <strong>{copySourceCode.trim()}</strong>
          </div>
        ) : (
          <div className={styles.editHint} data-testid={tid(testIdPrefix, 'edit-hint')}>
            <i className="fas fa-pen" aria-hidden /> Đang{' '}
            {isCreate ? 'tạo mới' : 'chỉnh sửa'} — Lưu hoặc Hủy
          </div>
        )}
      </div>
    </div>
  );
};

export const CatalogFormShell: React.FC<{
  testId: string;
  header: React.ReactNode;
  children: React.ReactNode;
}> = ({ testId, header, children }) => (
  <div className={styles.page} data-testid={testId}>
    <div className={styles.pageFormHeader}>{header}</div>
    <div className={styles.pageFormScroll}>{children}</div>
  </div>
);

export { styles as catalogFormChrome };
