/**
 * T-PERM-01 — permission codes for incidents (Auth stub until CommonLib mount).
 */
import { isPermissionsLocalModeActive } from '../../dev/isPermissionsLocalMode';

export const INCIDENT_PERMS = {
  read: 'rmms-field:incidents:read',
  create: 'rmms-field:incidents:write',
  update: 'rmms-field:incidents:write',
  delete: 'rmms-field:incidents:write',
} as const;

export type IncidentPermCode = (typeof INCIDENT_PERMS)[keyof typeof INCIDENT_PERMS];

export function hasIncidentPermission(code: IncidentPermCode): boolean {
  if (isPermissionsLocalModeActive()) return true;
  const bag = (window as unknown as { __LINM_PERMS__?: Record<string, boolean> })
    .__LINM_PERMS__;
  if (!bag) return true;
  return bag[code] === true;
}

export function incidentListPermissions() {
  return {
    canRead: hasIncidentPermission(INCIDENT_PERMS.read),
    canCreate: hasIncidentPermission(INCIDENT_PERMS.create),
    canUpdate: hasIncidentPermission(INCIDENT_PERMS.update),
    canDelete: hasIncidentPermission(INCIDENT_PERMS.delete),
  };
}
